"""Mandelbrot escape times computed on the GPU with wgpu, summarized on the CPU."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = """
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> xs: array<f32>;
@group(0) @binding(2) var<storage, read> ys: array<f32>;
@group(0) @binding(3) var<storage, read_write> times: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    let j = id.y;
    if (i >= params.width || j >= params.height) {
        return;
    }
    let cx = xs[i];
    let cy = ys[j];
    var zx: f32 = 0.0;
    var zy: f32 = 0.0;
    var n: u32 = 0u;
    loop {
        if (n >= params.limit || zx * zx + zy * zy > 4.0) {
            break;
        }
        let nx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nx;
        n = n + 1u;
    }
    times[j * params.width + i] = n;
}
"""


def parse_input(path):
    with open(path) as f:
        tokens = f.read().split()
    if len(tokens) < 7:
        raise ValueError("expected 7 values: width height limit x_min x_max y_min y_max")
    width, height, limit = (int(float(t)) for t in tokens[:3])
    x_min, x_max, y_min, y_max = (float(t) for t in tokens[3:7])
    return width, height, limit, x_min, x_max, y_min, y_max


def escape_times(width, height, limit, x_min, x_max, y_min, y_max):
    """Return an array of escape times (row-major, height x width) computed on the GPU."""
    # Per-axis coordinates, computed in double precision and handed to the kernel.
    xs = (x_min + (np.arange(width, dtype=np.float64) + 0.5) * (x_max - x_min) / width).astype(np.float32)
    ys = (y_min + (np.arange(height, dtype=np.float64) + 0.5) * (y_max - y_min) / height).astype(np.float32)
    params = np.array([width, height, limit, 0], dtype=np.uint32)

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    usage = wgpu.BufferUsage
    params_buf = device.create_buffer_with_data(data=params.tobytes(), usage=usage.UNIFORM)
    xs_buf = device.create_buffer_with_data(data=xs.tobytes(), usage=usage.STORAGE)
    ys_buf = device.create_buffer_with_data(data=ys.tobytes(), usage=usage.STORAGE)
    out_size = width * height * 4
    out_buf = device.create_buffer(size=out_size, usage=usage.STORAGE | usage.COPY_SRC)

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": params_buf.size}},
            {"binding": 1, "resource": {"buffer": xs_buf, "offset": 0, "size": xs_buf.size}},
            {"binding": 2, "resource": {"buffer": ys_buf, "offset": 0, "size": ys_buf.size}},
            {"binding": 3, "resource": {"buffer": out_buf, "offset": 0, "size": out_size}},
        ],
    )

    encoder = device.create_command_encoder()
    compute = encoder.begin_compute_pass()
    compute.set_pipeline(pipeline)
    compute.set_bind_group(0, bind_group)
    compute.dispatch_workgroups(
        (width + WORKGROUP - 1) // WORKGROUP, (height + WORKGROUP - 1) // WORKGROUP, 1
    )
    compute.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(out_buf)
    return np.frombuffer(data, dtype=np.uint32).copy()


def summarize(times, limit):
    times = np.asarray(times, dtype=np.int64)
    inside = int(np.count_nonzero(times == limit))
    escaped = times[times < limit]
    bins = np.bincount((8 * escaped) // limit, minlength=8)[:8]
    mean = float(escaped.mean()) if escaped.size else 0.0
    lines = [f"INSIDE {inside}"]
    lines += [f"BIN {b} {int(bins[b])}" for b in range(8)]
    lines.append(f"MEAN {mean:.3f}")
    return lines


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    width, height, limit, x_min, x_max, y_min, y_max = parse_input(argv[1])
    times = escape_times(width, height, limit, x_min, x_max, y_min, y_max)
    sys.stdout.write("\n".join(summarize(times, limit)) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

